from taf.rfrl.l3_call.cell.cloud_cell.cloud_cell import CloudCell
from taf.rfrl.l3_call.logger.l3_call_logger import log_input_and_output, log_to_console


class CloudNrCell(CloudCell):
    def __init__(self, cell_distname, vdu_aliases, shared_spectrum):
        super(CloudNrCell, self).__init__(cell_distname, vdu_aliases, shared_spectrum)
        self._type = "nr"

    def __str__(self):
        return "CloudNrCell cell instance for {0} cell type".format(self._type)

    def _is_dss(self):
        return False

    def _get_dss_pair(self):
        pass

    def _make_callable(self, delta):
        log_to_console("Making cell {} callable".format(self.distname))
        if self._is_cell_blocked():
            self._unblock_cell()

        if delta:
            log_to_console("Adding cellBarred: notBarred parameter "
                           "update for cell {} to delta".format(self.distname))
            delta.add_parameter_to_delta(dist_name=self.distname, parameter="cellBarred", value="notBarred")

    def _make_uncallable(self, delta):
        if self._shared_spectrum and not self._is_cell_blocked():
            log_to_console("Blocking cell {}".format(self.distname))
            self._block_cell()

        if not self._shared_spectrum and not self._is_cell_blocked():
            log_to_console("Adding cellBarred: barred parameter "
                           "update for cell {} to delta".format(self.distname))
            delta.add_parameter_to_delta(dist_name=self.distname, parameter="cellBarred", value="barred")

    @log_input_and_output
    def _get_cell_id(self):
        for cell in self._admin_du.get_vdu_cells_status(vdu_connection=self.vdu_alias):
            if cell["dist_names"]["config"] == self.distname:
                return cell["nr_cell_identity"]

    def _calculate_carrier_frequency(self, nrarfcn):
        if 0 <= int(nrarfcn) <= 599999:
            f_glob, f_ref_offs, n_ref_offs = 5, 0, 0
        elif 600000 <= int(nrarfcn) <= 2016666:
            f_glob, f_ref_offs, n_ref_offs = 15, 3000, 600000
        else:
            f_glob, f_ref_offs, n_ref_offs = 60, 24250.08, 2016667

        return f_ref_offs + f_glob * (int(nrarfcn) - n_ref_offs) * 10 ** -3

    def _is_beamforming_activated(self):
        return False

    def _get_beamforming_delay(self):
        return 0

    @log_input_and_output
    def _get_protocol_for_pcap_verification(self):
        return "ngap"

    @log_input_and_output
    def _get_ok_msgs_and_procedure_codes(self):
        return {
            "InitialUEMessage": 15,
            "UERadioCapabilityInfoIndication": 44,
            "InitialContextSetupResponse": 14
        }

    @log_input_and_output
    def _get_nok_msgs_and_procedure_codes(self):
        return {
            "UEContextReleaseComplete": 41
        }

    @log_input_and_output
    def _get_nok_structures(self):
        return []
